const D = { density: .55, scale: 1, energy: .6, weave: .45, speed: 1, hue: 190, x: .5, y: .5, style: 'teal-amber', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- coarse density buffer (Barry Martin's Hopalong histogram) ----
const BW = Math.max(360, Math.min(520, Math.round(width/2.6))), BH = Math.max(64, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1);
  S.bw = BW; S.bh = BH; S.dens = new Float32Array(BW * BH);
}
const g = S.g, dens = S.dens, NP = BW * BH;

// ---- seed-dependent attractor family ----
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.a0 = 0.9 + fr(1) * 0.9;   // 0.9..1.8
  S.b0 = 0.9 + fr(2) * 0.5;   // 0.9..1.4
  S.c0 = 0.6 + fr(3) * 3.4;   // 0.6..4.0
  S.pa = fr(4) * 6.283; S.pb = fr(5) * 6.283; S.pc = fr(6) * 6.283;
  S.hoff = fr(7);
  S.ext = null; S.cx = 0; S.cy = 0;   // force reframe
}

// ---- drift a,b,c on K.t (continuous, never re-phases; base drift survives speed=0) ----
const dr = K.t * (0.05 + P.speed * 0.06);
const a = S.a0 + 0.22 * Math.sin(dr * 0.53 + S.pa) + A.lowmid * 0.15;
const b = S.b0 + 0.12 * Math.sin(dr * 0.37 + S.pb);
const c = S.c0 + 0.90 * Math.sin(dr * 0.23 + S.pc);
const rot = dr * 0.6 + K.section * 0.18;       // slow global rotation → sheets re-weave
const cosR = Math.cos(rot), sinR = Math.sin(rot);

// ---- probe pass: auto-fit bounds ----
let px = 0.1, py = 0.0, minx = 1e9, maxx = -1e9, miny = 1e9, maxy = -1e9;
for (let i = 0; i < 1400; i++) {
  const sx = px < 0 ? -1 : 1;
  const nx = py - sx * Math.sqrt(Math.abs(b * px - c));
  const ny = a - px;
  px = nx; py = ny;
  if (!isFinite(px) || !isFinite(py)) { px = 0.1; py = 0.0; continue; }
  if (i > 60) { if (px < minx) minx = px; if (px > maxx) maxx = px; if (py < miny) miny = py; if (py > maxy) maxy = py; }
}
let cx = (minx + maxx) * 0.5, cy = (miny + maxy) * 0.5;
let ext = Math.max(maxx - minx, maxy - miny) * 0.5 * 1.15;
if (!isFinite(ext) || ext <= 0.4) ext = S.ext || 6;
ext = Math.min(ext, 40);
if (S.ext == null) { S.cx = cx; S.cy = cy; S.ext = ext; }
else { S.cx += (cx - S.cx) * 0.12; S.cy += (cy - S.cy) * 0.12; S.ext += (ext - S.ext) * 0.12; }
cx = S.cx; cy = S.cy; ext = S.ext;

// ---- accumulate iterates into density histogram ----
dens.fill(0);
const zoom = (Math.min(BW, BH) * 0.46) * P.scale / ext;
const ax = P.x * BW, ay = (1 - P.y) * BH;
const iters = Math.min(Math.round(90000 * (BW*BW)/40000), Math.round(NP * (0.9 + P.density * 2.8) + A.rms * 20000));
px = 0.1; py = 0.0;
for (let i = 0; i < iters; i++) {
  const sx = px < 0 ? -1 : 1;
  const nx = py - sx * Math.sqrt(Math.abs(b * px - c));
  const ny = a - px;
  px = nx; py = ny;
  if (!isFinite(px)) { px = 0.1; py = 0.0; continue; }
  if (i < 40) continue;
  const dx = px - cx, dy = py - cy;
  const rx = dx * cosR - dy * sinR, ry = dx * sinR + dy * cosR;
  const bx = (ax + rx * zoom) | 0, by = (ay + ry * zoom) | 0;
  if (bx >= 0 && bx < BW && by >= 0 && by < BH) dens[by * BW + bx] += 1;
}

// ---- palette LUT (128 entries, rebuilt each frame for smooth drift) ----
function hsv(h, s, v) {
  h = ((h % 360) + 360) % 360; const cc = v * s, xx = cc * (1 - Math.abs((h / 60) % 2 - 1)), m = v - cc;
  let r, gg, bb;
  if (h < 60) { r = cc; gg = xx; bb = 0; } else if (h < 120) { r = xx; gg = cc; bb = 0; }
  else if (h < 180) { r = 0; gg = cc; bb = xx; } else if (h < 240) { r = 0; gg = xx; bb = cc; }
  else if (h < 300) { r = xx; gg = 0; bb = cc; } else { r = cc; gg = 0; bb = xx; }
  return [r + m, gg + m, bb + m];
}
const hb = (P.hue + S.hoff * 30 + K.section * 12 + dr * 3) % 360;
const style = P.style;
const lutR = S.lutR || (S.lutR = new Uint8ClampedArray(128));
const lutG = S.lutG || (S.lutG = new Uint8ClampedArray(128));
const lutB = S.lutB || (S.lutB = new Uint8ClampedArray(128));
for (let n = 0; n < 128; n++) {
  const t = n / 127; let r, gg, bl;
  if (style === 'plasma') {
    const col = hsv(hb + 120 - 135 * Math.pow(t, 0.8), 0.95 - 0.5 * t, 0.06 + 0.97 * Math.pow(t, 0.7)); r = col[0]; gg = col[1]; bl = col[2];
  } else if (style === 'ember') {
    r = Math.min(1, 1.7 * t + 0.03); gg = Math.min(1, Math.max(0, 1.9 * t - 0.72)); bl = Math.min(1, Math.max(0, 2.6 * t - 1.95));
  } else if (style === 'ice') {
    const col = hsv(hb + 15 - 30 * t, 0.86 - 0.8 * Math.pow(t, 1.2), 0.08 + 0.95 * Math.pow(t, 0.7)); r = col[0]; gg = col[1]; bl = col[2];
  } else if (style === 'pencil') {
    const f = Math.pow(t, 0.62); r = 0.93 + (0.13 - 0.93) * f; gg = 0.915 + (0.14 - 0.915) * f; bl = 0.87 + (0.18 - 0.87) * f;
  } else { // teal-amber (default): teal low -> amber high -> white hot
    const col = hsv(hb - 150 * Math.pow(t, 0.85), 0.92 - 0.72 * Math.pow(t, 1.4), 0.07 + 0.95 * Math.pow(t, 0.72)); r = col[0]; gg = col[1]; bl = col[2];
  }
  lutR[n] = r * 255; lutG[n] = gg * 255; lutB[n] = bl * 255;
}

// ---- tone-map density → color, with moiré striation + galactic glow floor ----
g.loadPixels(); const pix = g.pixels;
const expo = (0.45 + P.energy * 1.3) * (0.8 + K.intensity * 0.5) + A.bass * 0.8 + A.rms * 0.4 + K.pulse * 0.15;
const LOGD = Math.log(1 + 22);
const weave = P.weave, wfreq = 5 + weave * 22;
const ambientAmt = style === 'pencil' ? 0 : 0.15;
const cxp = BW * 0.5, cyp = BH * 0.5, rr = 1 / (BW * BW * 0.32);
for (let k = 0; k < NP; k++) {
  const cnt = dens[k];
  let nv = cnt > 0 ? Math.log(1 + cnt * expo) / LOGD : 0;
  if (nv > 1) nv = 1;
  const band = 0.65 + 0.35 * Math.sin(nv * wfreq * 6.28318);
  let v = nv * (1 - weave) + nv * band * weave;
  if (ambientAmt > 0) {
    const ix = k % BW, iy = (k / BW) | 0, ddx = ix - cxp, ddy = iy - cyp;
    const amb = ambientAmt * Math.exp(-(ddx * ddx + ddy * ddy) * rr);
    if (amb > v) v = amb;
  }
  if (v > 1) v = 1; else if (v < 0) v = 0;
  const li = (v * 127) | 0, o = k * 4;
  pix[o] = lutR[li]; pix[o + 1] = lutG[li]; pix[o + 2] = lutB[li]; pix[o + 3] = 255;
}
g.updatePixels();

// ---- draw ----
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// ---- audio sparkle on top of clk baseline (partial, never full-frame flash) ----
if (A.treble > 0.02 || A.bass > 0.02) {
  push(); blendMode(ADD); noStroke();
  fill((hb + 40) % 360, 45, 100, (A.treble * 0.5 + A.bass * 0.35) * P.energy * 20);
  rect(0, 0, width, height);
  blendMode(BLEND); pop();
}
